package com.javacodingagent.infrastructure.trace;
import com.fasterxml.jackson.databind.ObjectMapper; import com.javacodingagent.trace.*; import javax.sql.DataSource; import java.sql.*; import java.util.*;
/** MySQL-backed trace store using the stage-one schema. */
public class JdbcTraceStore implements TraceStore { private final DataSource dataSource; private final ObjectMapper mapper; public JdbcTraceStore(DataSource dataSource, ObjectMapper mapper) { this.dataSource = dataSource; this.mapper = mapper; } public void append(TraceEvent event) { String sql = "INSERT INTO agent_trace_step(trace_id,task_id,sequence_number,agent_role,step_type,step_name,output_summary,step_status,start_time,end_time,duration_ms) VALUES(?,?,?,?,?,?,?,?,NOW(),NOW(),0)"; try (Connection c = dataSource.getConnection(); PreparedStatement p = c.prepareStatement(sql)) { p.setString(1,event.traceId()); p.setLong(2,event.taskId()); p.setLong(3,event.sequence()); p.setString(4,event.role()); p.setString(5,event.type()); p.setString(6,event.type()); p.setString(7,event.summary()); p.setString(8,"SUCCEEDED"); p.executeUpdate(); } catch (SQLException e) { throw new IllegalStateException("Trace persistence failed", e); } } public List<TraceEvent> findByTask(Long taskId) { String sql="SELECT trace_id,task_id,sequence_number,step_type,agent_role,output_summary,create_time FROM agent_trace_step WHERE task_id=? ORDER BY sequence_number"; List<TraceEvent> result=new ArrayList<>(); try(Connection c=dataSource.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,taskId);try(ResultSet r=p.executeQuery()){while(r.next())result.add(new TraceEvent(r.getString(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),Map.of(),r.getTimestamp(7).toInstant()));}}catch(SQLException e){throw new IllegalStateException("Trace query failed",e);}return result; } }
